solution.exercise.c:
#include "exercise.h"
#include <ctype.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
void graph_free(graph *g) {
    free(g->nodes);
    free(g->edges);
    free(g->attributes);
    memset(g, 0, sizeof *g);
}
const char *graph_create(graph *g, const graph_item *x, size_t n) {
    memset(g, 0, sizeof *g);
    if (n && !x)
        return "Graph data malformed";
    for (size_t i = 0; i < n; i++) {
        const graph_item *p = x + i;
        const char *error = NULL;
        if (p->arity < 3)
            error = "Graph item incomplete";
        else if (p->kind == 0 && p->arity != 3)
            error = "Node is malformed";
        else if (p->kind == 1 && p->arity != 4)
            error = "Edge is malformed";
        else if (p->kind == 2 && p->arity != 3)
            error = "Attribute is malformed";
        else if (p->kind < 0 || p->kind > 2)
            error = "Unknown item";
        if (error) {
            graph_free(g);
            return error;
        }
        if (p->kind == 0) {
            g->nodes = (graph_item *)realloc(g->nodes,
                                             (g->node_count + 1) * sizeof(graph_item));
            g->nodes[g->node_count++] = *p;
        } else if (p->kind == 1) {
            g->edges = (graph_item *)realloc(g->edges,
                                             (g->edge_count + 1) * sizeof(graph_item));
            g->edges[g->edge_count++] = *p;
        } else {
            size_t k = 0;
            while (k < g->attribute_count && strcmp(g->attributes[k].key, p->name))
                k++;
            if (k == g->attribute_count) {
                g->attributes = (attribute *)realloc(
                    g->attributes, (++g->attribute_count) * sizeof(attribute));
            }
            g->attributes[k].key = p->name;
            g->attributes[k].value = p->destination;
        }
    }
    return NULL;
}

tests.test_exercise.c:
#include "exercise.h"
#include <assert.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
static bool positive(int x) { return x > 0; }
static bool bstring(const void *p) { return (*(const char *const *)p)[0] == 98; }
static void string_length(const void *p, void *out) {
    *(size_t *)out = strlen(*(const char *const *)p);
}
int main(void) {
    graph_item x[] = {{0, 3, "a", NULL, NULL, 0},
                      {1, 4, "a", "b", NULL, 0},
                      {2, 3, "color", "red", NULL, 0},
                      {2, 3, "color", "blue", NULL, 0}};
    graph g;
    assert(!graph_create(&g, x, 4));
    assert(g.node_count == 1 && g.edge_count == 1 && g.attribute_count == 1 &&
           !strcmp(g.attributes[0].value, "blue"));
    graph_free(&g);
    graph_item bad = {0, 4, "a", NULL, NULL, 0};
    assert(!strcmp(graph_create(&g, &bad, 1), "Node is malformed"));
    bad.kind = 99;
    bad.arity = 3;
    assert(!strcmp(graph_create(&g, &bad, 1), "Unknown item"));
    bad.arity = 1;
    assert(!strcmp(graph_create(&g, &bad, 1), "Graph item incomplete"));

    return 0;
}
